from __future__ import annotations

from source_items import Item


def item(
    question: str,
    correct: str,
    wrong: str,
    distractor_1: str,
    distractor_2: str,
    note: str,
) -> Item:
    return Item(
        question,
        correct,
        wrong,
        distractor_1,
        distractor_2,
        note,
    )


