def build_geography_items() -> dict[str, list[Item]]:
    easy = build_easy_items()
    medium = build_medium_items()
    hard = build_hard_items()

    if len(easy) != 88:
        raise ValueError(
            f"Expected 88 easy geography items, found {len(easy)}"
        )

    if len(hard) != 22:
        raise ValueError(
            f"Expected 22 hard geography items, found {len(hard)}"
        )

    return {
        "easy": easy,
        "medium": medium,
        "hard": hard,
    }
